import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const rootDir = path.resolve(__dirname, '..');
const srcDir = path.join(rootDir, 'roblox-plugin', 'src');
const outDir = path.join(rootDir, 'plugin-build');

if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

function getLuauFiles(dir, baseDir = dir) {
  let files = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files = files.concat(getLuauFiles(fullPath, baseDir));
    } else if (entry.name.endsWith('.luau') || entry.name.endsWith('.lua')) {
      const relPath = path.relative(baseDir, fullPath).replace(/\\/g, '/');
      files.push({ relPath, fullPath });
    }
  }
  return files;
}

const allFiles = getLuauFiles(srcDir);
const mainFile = allFiles.find((f) => f.relPath === 'PluginMain.server.luau' || f.relPath === 'Main.server.luau');
const moduleFiles = allFiles.filter((f) => f !== mainFile);

let bundledCode = `--!strict
-- Roblox Studio Universal MCP - Standalone Embedded Plugin Bundle
-- Auto-generated by bundle-plugin.js

local _MODULE_CACHE = {}
local _MODULE_LOADERS = {}

local function _resolveModuleName(rawPath: string): string
	local cleaned = rawPath:gsub("\\.luau$", ""):gsub("\\.lua$", "")
	-- Normalize common aliases
	if _MODULE_LOADERS[cleaned] then return cleaned end
	for key, _ in pairs(_MODULE_LOADERS) do
		if key:sub(-#cleaned) == cleaned or key:find(cleaned, 1, true) then
			return key
		end
	end
	return cleaned
end

local function _requireModule(moduleName: string)
	local resolved = _resolveModuleName(moduleName)
	if _MODULE_CACHE[resolved] ~= nil then
		return _MODULE_CACHE[resolved]
	end
	local loader = _MODULE_LOADERS[resolved]
	if not loader then
		-- Fallback to fuzzy search
		for key, l in pairs(_MODULE_LOADERS) do
			if key:find(moduleName) or moduleName:find(key) then
				local res = l()
				_MODULE_CACHE[key] = res
				return res
			end
		end
		error(string.format("[UniversalMCP Loader] Module '%s' not found in bundle.", moduleName))
	end
	local result = loader()
	_MODULE_CACHE[resolved] = result
	return result
end

`;

for (const mod of moduleFiles) {
  const nameWithoutExt = mod.relPath
    .replace(/\.server\.(luau|lua)$/, '')
    .replace(/\.client\.(luau|lua)$/, '')
    .replace(/\.(luau|lua)$/, '');
  const content = fs.readFileSync(mod.fullPath, 'utf8');

  // Replace any require(script...) statement with _requireModule
  let processed = content.replace(/require\s*\(\s*script([^)]+)\)/g, (_match, p1) => {
    // Convert property access like .Parent.Parent.Core.State to path
    const parts = p1.split('.').filter(Boolean);
    // Remove "Parent" tokens and build module name
    const validParts = parts.filter((p) => p !== 'Parent' && p !== 'script');
    const pathStr = validParts.join('/');
    return `_requireModule("${pathStr}")`;
  });

  bundledCode += `_MODULE_LOADERS["${nameWithoutExt}"] = function()\n${processed}\nend\n\n`;
}

if (mainFile) {
  let mainContent = fs.readFileSync(mainFile.fullPath, 'utf8');
  let processedMain = mainContent.replace(/require\s*\(\s*script([^)]+)\)/g, (_match, p1) => {
    const parts = p1.split('.').filter(Boolean);
    const validParts = parts.filter((p) => p !== 'Parent' && p !== 'script');
    const pathStr = validParts.join('/');
    return `_requireModule("${pathStr}")`;
  });

  bundledCode += `\n-- MAIN ENTRY POINT\n${processedMain}\n`;
}

// 1. Output .luau file
const luauPath = path.join(outDir, 'RobloxUniversalMCP.luau');
fs.writeFileSync(luauPath, bundledCode, 'utf8');

// 2. Output .lua file
const luaPath = path.join(outDir, 'RobloxUniversalMCP.lua');
fs.writeFileSync(luaPath, bundledCode, 'utf8');

console.log(`[Plugin Bundler] Successfully generated standalone bundle at: ${luaPath}`);
